-- Estrutura equivalente às tabelas financeiras reais (colunas/constraints lidas do banco real).
DROP TABLE public.gastos;
CREATE TABLE public.categorias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, nome text NOT NULL, icon_name text NOT NULL, color_var text NOT NULL, criada_pelo_usuario boolean NOT NULL DEFAULT false, legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.cartoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, nome text NOT NULL, banco text NOT NULL DEFAULT '', limite_total numeric NOT NULL DEFAULT 0, dia_fechamento smallint NOT NULL DEFAULT 1, dia_vencimento smallint NOT NULL DEFAULT 10, cor text NOT NULL DEFAULT '#8b5cf6', observacao text, legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.gastos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, categoria_id uuid REFERENCES public.categorias(id) ON DELETE SET NULL, descricao text NOT NULL, valor numeric NOT NULL, data date NOT NULL, estabelecimento text NOT NULL DEFAULT '', forma_pagamento text NOT NULL, observacao text, imagem_url text, mes smallint NOT NULL, ano integer NOT NULL, confirmado boolean NOT NULL DEFAULT true, tipo_gasto text NOT NULL DEFAULT 'unico', parcela_atual smallint, total_parcelas smallint, grupo_parcelamento_id uuid, recorrencia_id uuid, essencial boolean, gasto_fixo boolean, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), cartao_id uuid, horario text, origem text, import_batch_id uuid, id_operacao_banco text, invoice_month text, fornecedor_id uuid, offline_client_id text, bem_id uuid, fatura_competencia text CHECK (fatura_competencia IS NULL OR fatura_competencia ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'), deleted_at timestamptz, UNIQUE (user_id, id));
CREATE TABLE public.receitas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, descricao text NOT NULL, valor numeric NOT NULL, data date NOT NULL, tipo text NOT NULL, recorrente boolean NOT NULL DEFAULT false, recorrencia_id uuid, mes smallint NOT NULL, ano integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), origem text, horario text, import_batch_id uuid, id_operacao_banco text, cliente_id uuid, offline_client_id text, deleted_at timestamptz, deleted_reason text, deleted_source text, CONSTRAINT receitas_valor_valid_range_check CHECK (deleted_at IS NOT NULL OR (valor > 0 AND valor <= 999999999.99)));
CREATE TABLE public.extratos_importados (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, nome_arquivo text, banco text, tipo_origem text NOT NULL DEFAULT 'pdf', data_importacao timestamptz NOT NULL DEFAULT now(), periodo_inicio date, periodo_fim date, qtd_movimentacoes integer NOT NULL DEFAULT 0, qtd_duplicadas_ignoradas integer NOT NULL DEFAULT 0, total_receitas numeric NOT NULL DEFAULT 0, total_despesas numeric NOT NULL DEFAULT 0, total_guardado numeric NOT NULL DEFAULT 0, total_transferencias numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'importado', observacao text, reverted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.imported_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, provider text NOT NULL, provider_transaction_id text NOT NULL, amount numeric, status text, occurred_at timestamptz);
CREATE TRIGGER trg_gastos_updated_at BEFORE UPDATE ON public.gastos FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER trg_receitas_updated_at BEFORE UPDATE ON public.receitas FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
GRANT ALL ON public.gastos, public.receitas, public.extratos_importados, public.categorias, public.cartoes, public.imported_transactions TO service_role;
